function bindLanding(){document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{state.mode=b.dataset.mode;save();render()});const s=document.querySelector('#start');if(s)s.onclick=()=>{state.started=true;render()}}
function bindApp(){document.querySelectorAll('[data-axis]').forEach(b=>b.onclick=()=>{state.axis=b.dataset.axis;render()});document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{state.ans[b.dataset.id]=b.dataset.answer;save();render()});document.querySelectorAll('[data-note]').forEach(t=>t.oninput=()=>{state.notes[t.dataset.note]=t.value;save()});document.querySelector('#search').oninput=e=>{state.search=e.target.value;render()};document.querySelector('#print').onclick=document.querySelector('#pdf').onclick=printComplianceReport;document.querySelector('#close').onclick=document.querySelector('#back').onclick=()=>{state.started=false;render()};document.querySelector('#reset').onclick=()=>{if(confirm('Effacer toutes les rÃ©ponses ?')){state.ans={};state.notes={};save();render()}}}const baseRender=render;render=function(){baseRender();injectContact()};

