 wrap.querySelector('.support-mail').onclick=()=>location.href='mailto:inno.twa@gmail.com?subject='+encodeURIComponent('Demande dâ€™accompagnement â€” ConformitÃ© RGPD')+'&body='+encodeURIComponent('Bonjour Innocent,\n\nJe souhaite Ãªtre accompagnÃ©(e) dans ma dÃ©marche de conformitÃ© RGPD.\n\nContexte / besoin :\n\nCordialement,');
 const dates=[],d=new Date();for(let i=1;dates.length<8;i++){const n=new Date(d);n.setDate(d.getDate()+i);if(n.getDay()!==0&&n.getDay()!==6)dates.push(n)}
 const dateBox=wrap.querySelector('.calendar-grid'),timeBox=wrap.querySelector('.time-grid'),status=wrap.querySelector('.booking-status');
